#define main legacy_main
#include "study_native_source.cuh"
#undef main
int main(){const int N=nx*ny*nz;std::vector<float>v(N),cs(N),ns(N),cr(N),nr(N),image(N,.5f),c(N),d(N),im(N);for(int i=0;i<N;i++){v[i]=float(1+i%3)/256;cs[i]=float(i%17-8)/16;ns[i]=float(i%13-6)/16;cr[i]=float(i%11-5)/32;nr[i]=float(i%7-3)/32;}float aa[5]={float(-1./560),float(8./315),-.2f,1.6f,float(-1435./504)};std::vector<double>wc(cr.begin(),cr.end()),wd(nr.begin(),nr.end()),wi(N,.5);for(int rep=0;rep<5;rep++)for(int z=4;z<nz-4;z++)for(int y=4;y<ny-4;y++)for(int x=4;x<nx-4;x++){int i=indexTo1D(x,y,z);auto lap=[&](const std::vector<float>&f){double sum=double(aa[0])*f[i];for(int r=1;r<=4;r++)sum+=double(aa[r])*(double(f[i+r])+f[i-r]+f[i+r*nx]+f[i-r*nx]+f[i+r*nx*ny]+f[i-r*nx*ny]);return sum;};wc[i]=2.*cs[i]-wc[i]+double(v[i])*lap(cs);wd[i]=2.*ns[i]-wd[i]+double(v[i])*lap(ns);wi[i]=wc[i]*wd[i];}float *V,*CS,*NS,*CR,*NR,*I,*A;cudaMalloc(&V,N*4);cudaMalloc(&CS,N*4);cudaMalloc(&NS,N*4);cudaMalloc(&CR,N*4);cudaMalloc(&NR,N*4);cudaMalloc(&I,N*4);cudaMalloc(&A,20);cudaMemcpy(V,v.data(),N*4,cudaMemcpyHostToDevice);cudaMemcpy(CS,cs.data(),N*4,cudaMemcpyHostToDevice);cudaMemcpy(NS,ns.data(),N*4,cudaMemcpyHostToDevice);cudaMemcpy(CR,cr.data(),N*4,cudaMemcpyHostToDevice);cudaMemcpy(NR,nr.data(),N*4,cudaMemcpyHostToDevice);cudaMemcpy(I,image.data(),N*4,cudaMemcpyHostToDevice);cudaMemcpy(A,aa,20,cudaMemcpyHostToDevice);auto run=[&](){rtm8<<<dim3((nx+15)/16,(ny+15)/16,nz),dim3(16,16)>>>(V,CS,NS,CR,NR,I,A,N);};run();if(cudaDeviceSynchronize()!=cudaSuccess)return 2;for(int trial=1;trial<=5;trial++){cudaMemcpy(CR,cr.data(),N*4,cudaMemcpyHostToDevice);cudaMemcpy(NR,nr.data(),N*4,cudaMemcpyHostToDevice);cudaMemcpy(I,image.data(),N*4,cudaMemcpyHostToDevice);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int rep=0;rep<5;rep++)run();if(cudaDeviceSynchronize()!=cudaSuccess)return 2;double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/5;cudaMemcpy(c.data(),CR,N*4,cudaMemcpyDeviceToHost);cudaMemcpy(d.data(),NR,N*4,cudaMemcpyDeviceToHost);cudaMemcpy(im.data(),I,N*4,cudaMemcpyDeviceToHost);double err=0;bool ok=true;std::vector<float>out;for(int part=0;part<3;part++){auto&f=part==0?c:part==1?d:im;auto&w=part==0?wc:part==1?wd:wi;for(int i=0;i<N;i++){err=std::max(err,fabs(double(f[i])-w[i]));ok=ok&&std::isfinite(f[i])&&fabs(double(f[i])-w[i])<=.1;}out.insert(out.end(),f.begin(),f.end());}char path[64];snprintf(path,64,"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(out.data(),4,out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.15g,\"correct\":%s,\"checked_values\":46080,\"max_abs_error\":%.15g,\"timing_region\":\"native_behavior_five_odd_recurrence_kernel_mean\",\"jit_excluded\":true,\"internal_repeats\":5,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":46080,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",err,path);if(!ok)return 1;}cudaFree(V);cudaFree(CS);cudaFree(NS);cudaFree(CR);cudaFree(NR);cudaFree(I);cudaFree(A);}
